package com.bank.shardchallenge.model;
import java.math.BigDecimal;
import java.util.*;

public class Shard {
    private final String name; private final Map<String, BigDecimal> accounts = new HashMap<>();
    public Shard(String name) { this.name = name; }
    public String getName() { return name; }
    public void put(String id, BigDecimal bal) { accounts.put(id, bal); }
    public BigDecimal balance(String id) { return accounts.get(id); }
    public void setBalance(String id, BigDecimal bal) { accounts.put(id, bal); }
    public BigDecimal total() { return accounts.values().stream().reduce(BigDecimal.ZERO, BigDecimal::add); }
    public boolean has(String id) { return accounts.containsKey(id); }
}
