package com.bank.shardchallenge.service;
import com.bank.shardchallenge.model.Shard;
import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class ShardedBank {
    private static final Logger log = Logger.getLogger(ShardedBank.class.getName());
    static {
        Handler h = new ConsoleHandler(); h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false); log.addHandler(h);
    }
    private final List<Shard> shards;
    public ShardedBank(List<Shard> shards) { this.shards = shards; }

    private Shard shardOf(String id) {
        return shards.stream().filter(s -> s.has(id)).findFirst().orElseThrow();
    }
    // CROSS-SHARD QUERY: scatter-gather sum across all shards
    public BigDecimal crossShardTotal() {
        BigDecimal total = shards.stream().map(Shard::total).reduce(BigDecimal.ZERO, BigDecimal::add);
        log.info(() -> "SCATTER-GATHER total across " + shards.size() + " shards = " + total);
        return total;
    }
    // CROSS-SHARD TXN: Saga — debit on one shard, credit on another, compensate on failure
    public boolean crossShardTransfer(String from, String to, BigDecimal amount, boolean creditFails) {
        Shard src = shardOf(from), dst = shardOf(to);
            if (src.balance(from).compareTo(amount) < 0) { log.warning(() -> "insufficient funds");
            return false; }
        src.setBalance(from, src.balance(from).subtract(amount));               // step 1: debit
        log.info(() -> "SAGA debit " + from + " on " + src.getName());
        if (creditFails) {                                                      // step 2 fails
            src.setBalance(from, src.balance(from).add(amount));                // compensate step 1
            log.severe(() -> "SAGA credit failed on " + dst.getName() + " → compensated debit (rolled back)");
            return false;
        }
        dst.setBalance(to, dst.balance(to).add(amount));
        log.info(() -> "SAGA credit " + to + " on " + dst.getName() + " → committed");
        return true;
    }
}
