package com.bank.shardchallenge;
import com.bank.shardchallenge.model.Shard;
import com.bank.shardchallenge.service.ShardedBank;
import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class ChallengeDemo {
    public static void main(String[] args) {
        Shard s0 = new Shard("shard_0"); s0.put("CUR3001", new BigDecimal("250000"));
        Shard s1 = new Shard("shard_1"); s1.put("SAV2001", new BigDecimal("1000000"));
        ShardedBank bank = new ShardedBank(List.of(s0, s1));
        bank.crossShardTotal();
        bank.crossShardTransfer("SAV2001", "CUR3001", new BigDecimal("50000"), false); // success
        bank.crossShardTransfer("SAV2001", "CUR3001", new BigDecimal("50000"), true);  // fails → compensate
    }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n", r.getMillis(), r.getLevel(), formatMessage(r));
    }
}
